package app.kinnect.live;
import android.content.Context;
import android.security.keystore.*;
import android.util.Base64;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
/** Session encrypted with a non-exportable Android Keystore key. Never stores passwords. */
final class SessionStore {
 byte[] sealCache(String label,byte[] data)throws Exception {try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());c.updateAAD(label.getBytes("UTF-8"));byte[] iv=c.getIV(),body=c.doFinal(data),result=new byte[1+iv.length+body.length];result[0]=(byte)iv.length;System.arraycopy(iv,0,result,1,iv.length);System.arraycopy(body,0,result,1+iv.length,body.length);return result;}catch(InvalidKeyException|KeyStoreException|ProviderException e){invalidateKey();throw e;}}
 byte[] openCache(String label,byte[] data)throws Exception {if(data.length<30||data[0]!=12)throw new GeneralSecurityException("Invalid cache");try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,java.util.Arrays.copyOfRange(data,1,13)));c.updateAAD(label.getBytes("UTF-8"));return c.doFinal(data,13,data.length-13);}catch(InvalidKeyException|KeyStoreException|ProviderException e){invalidateKey();throw e;}}
 private final Context context;
 private SecretKey cachedKey;
 SessionStore(Context context){this.context=context.getApplicationContext();}
 private synchronized void invalidateKey(){cachedKey=null;}
 private synchronized javax.crypto.SecretKey key() throws Exception {if(cachedKey!=null)return cachedKey;try{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias("kinnect_session")){javax.crypto.SecretKey existing=(javax.crypto.SecretKey)store.getKey("kinnect_session",null);if(existing!=null){cachedKey=existing;return existing;}}KeyGenerator gen=KeyGenerator.getInstance("AES","AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder("kinnect_session",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());cachedKey=gen.generateKey();return cachedKey;}catch(Exception e){cachedKey=null;throw e;}}
 private static String originKey(String origin)throws Exception{byte[] digest=MessageDigest.getInstance("SHA-256").digest(origin.getBytes("UTF-8"));StringBuilder sb=new StringBuilder("v2_");for(int i=0;i<16&&i<digest.length;i++)sb.append(String.format(java.util.Locale.ROOT,"%02x",digest[i]&255));return sb.toString();}
 synchronized void save(String origin,String cookie){try{android.content.SharedPreferences p=context.getSharedPreferences("native_session",0);String k=originKey(origin);if(cookie.isEmpty()){android.content.SharedPreferences.Editor ed=p.edit().remove(k);if(origin.equals(p.getString("origin","")))ed.remove("origin").remove("value");ed.apply();return;}Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());c.updateAAD(origin.getBytes("UTF-8"));String value=Base64.encodeToString(c.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(c.doFinal(cookie.getBytes("UTF-8")),Base64.NO_WRAP);p.edit().putString(k,value).apply();}catch(Exception failure){if(failure instanceof InvalidKeyException||failure instanceof KeyStoreException||failure instanceof ProviderException)invalidateKey();try{context.getSharedPreferences("native_session",0).edit().remove(originKey(origin)).apply();}catch(Exception ignored){}}}
 /** Đăng xuất: xoá phiên đã lưu bất kể origin. */
 synchronized void wipe(){context.getSharedPreferences("native_session",0).edit().clear().apply();}
 synchronized String load(String origin){try{android.content.SharedPreferences p=context.getSharedPreferences("native_session",0);String raw=p.getString(originKey(origin),"");if(raw.isEmpty()&&origin.equals(p.getString("origin","")))raw=p.getString("value","");if(raw.isEmpty())return "";String[] parts=raw.split(":");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));c.updateAAD(origin.getBytes("UTF-8"));return new String(c.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),"UTF-8");}catch(Exception failure){if(failure instanceof InvalidKeyException||failure instanceof KeyStoreException||failure instanceof ProviderException)invalidateKey();return "";}}
 // Thẻ "nhớ thiết bị" để đăng nhập nhanh: lưu riêng theo từng origin, không bị xoá khi đăng xuất.
 synchronized void saveDevice(String origin,String value){try{android.content.SharedPreferences p=context.getSharedPreferences("native_device",0);String k=originKey(origin);if(value==null||value.isEmpty()){android.content.SharedPreferences.Editor ed=p.edit().remove(k);if(origin.equals(p.getString("origin","")))ed.remove("origin").remove("value");ed.apply();return;}Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());c.updateAAD(origin.getBytes("UTF-8"));String encoded=Base64.encodeToString(c.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(c.doFinal(value.getBytes("UTF-8")),Base64.NO_WRAP);p.edit().putString(k,encoded).apply();}catch(Exception failure){if(failure instanceof InvalidKeyException||failure instanceof KeyStoreException||failure instanceof ProviderException)invalidateKey();try{context.getSharedPreferences("native_device",0).edit().remove(originKey(origin)).apply();}catch(Exception ignored){}}}
 synchronized String loadDevice(String origin){try{android.content.SharedPreferences p=context.getSharedPreferences("native_device",0);String raw=p.getString(originKey(origin),"");if(raw.isEmpty()&&origin.equals(p.getString("origin","")))raw=p.getString("value","");if(raw.isEmpty())return "";String[] parts=raw.split(":");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));c.updateAAD(origin.getBytes("UTF-8"));return new String(c.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),"UTF-8");}catch(Exception failure){if(failure instanceof InvalidKeyException||failure instanceof KeyStoreException||failure instanceof ProviderException)invalidateKey();return "";}}
}
